from collections import deque

class Solution:
    def swimInWater(self, grid):
        n = len(grid)
        def ok(t):
            if grid[0][0] > t:
                return False
            seen = [[False]*n for _ in range(n)]
            q = deque([(0, 0)])
            seen[0][0] = True
            while q:
                i, j = q.popleft()
                if i == n-1 and j == n-1:
                    return True
                for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < n and not seen[ni][nj] and grid[ni][nj] <= t:
                        seen[ni][nj] = True
                        q.append((ni, nj))
            return False
        lo, hi = max(grid[0][0], grid[-1][-1]), n*n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

