import java.util.*;

class Solution {
    public int swimInWater(int[][] grid) {
        int n = grid.length;
        int lo = Math.max(grid[0][0], grid[n-1][n-1]), hi = n * n - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (reachable(grid, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean reachable(int[][] grid, int t) {
        int n = grid.length;
        if (grid[0][0] > t) return false;
        boolean[][] seen = new boolean[n][n];
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == n-1 && cur[1] == n-1) return true;
            int[] di = {1,-1,0,0}, dj = {0,0,1,-1};
            for (int k = 0; k < 4; k++) {
                int ni = cur[0] + di[k], nj = cur[1] + dj[k];
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && !seen[ni][nj] && grid[ni][nj] <= t) {
                    seen[ni][nj] = true;
                    q.add(new int[]{ni, nj});
                }
            }
        }
        return false;
    }
}

