        int[] di = {1,-1,0,0}, dj = {0,0,1,-1};
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int d = top[0], i = top[1], j = top[2];
            if (i == n-1 && j == n-1) return d;
            if (d > dist[i][j]) continue;
            for (int k = 0; k < 4; k++) {
                int ni = i + di[k], nj = j + dj[k];
