class Solution:
    def swimInWater(self, grid):
        n = len(grid)
        if n == 1:
            return grid[0][0]
        parent = list(range(n * n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
        active = [False] * (n * n)
        cells = sorted((grid[i][j], i * n + j) for i in range(n) for j in range(n))
        for h, idx in cells:
            active[idx] = True
            i, j = divmod(idx, n)
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < n and active[ni * n + nj]:
                    union(idx, ni * n + nj)
            if active[0] and active[n * n - 1] and find(0) == find(n * n - 1):
                return h
        return grid[-1][-1]

